import java.io.*;

public class D {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            all.append(line).append('\n');
        }
        String[] tokens = all.toString().trim().split("\\s+");
        long n = Long.parseLong(tokens[0]);
        long m = Long.parseLong(tokens[1]);
        System.out.println(compute(n, m));
    }

    static long compute(long n, long m) {
        if (m < n) {
            n ^= m;
            m ^= n;
            n ^= m;
        }
        if (n == 1) return row(m);
        if (n == 2) return two(m);
        return 2 * (n * m / 2);
    }

    static long row(long m) {
        long base = 6 * (m / 6);
        switch ((int)(m % 6)) {
            case 5: return base + 4;
            case 4: return base + 2;
            default: return base;
        }
    }

    static long two(long m) {
        if (m == 3) return 4;
        if (m == 7) return 12;
        return m < 3 ? 0 : 2 * m;
    }
}
